// Access the first item's JSON data directly
const rawData = $input.first().json;

// Check if the expected array exists
if (!rawData || !rawData.assetSearchResults || rawData.assetSearchResults.length === 0) {
  return [{ json: { error: "No properties found or API structure changed.", debug_keys: Object.keys(rawData || {}) } }];
}

const properties = rawData.assetSearchResults;
const results = [];

for (const item of properties) {

  // 1. Extract the Address 
  let description = item.assetShortDescription || "N/A";
  let address = description;

  if (description.includes(" - ")) {
    address = description.split(" - ").slice(1).join(" - ").trim();
  }

  // 2. Extract location info
  const city = item.locationCity || "N/A";
  const state = item.locationState || "";
  const county = city !== "N/A" ? `${city}` : "N/A - Check Listing";

  // 3. Format Dates
  let saleDate = item.assetAuctionEndDate || "";
  let biddingDate = item.assetAuctionStartDate || "";
  let biddingTime = "";

  if (saleDate && saleDate.includes("T")) {
    biddingTime = saleDate.split("T")[1].replace("Z", "");
    saleDate = saleDate.split("T")[0];
  }
  if (biddingDate && biddingDate.includes("T")) {
    biddingDate = biddingDate.split("T")[0];
  }

  // 4. Determine status
  let status = "Active";
  const timeRemaining = item.timeRemaining || "";
  if (timeRemaining.toLowerCase().includes("sold")) status = "Sold";
  else if (timeRemaining.toLowerCase().includes("closed")) status = "Closed";

  // 5. Build auction URL
  const assetId = item.assetId || item.id || "";
  const auctionUrl = assetId ? `https://www.govdeals.com/asset/${assetId}` : "";

  // 6. Build unique ID for deduplication
  const uniqueId = `govdeals|${county}|${address}`.toLowerCase().replace(/\s+/g, '');

  results.push({
    json: {
      property_address: address,
      county: county,
      state: state,
      source: "GovDeals",
      status: status,
      sale_date: saleDate,
      bidding_date: biddingDate,
      bidding_time: biddingTime,
      current_bid: item.currentBid || 0,
      auction_url: auctionUrl,
      time_remaining: timeRemaining,
      unique_id: uniqueId
    }
  });
}

console.log(`✅ GovDeals: ${results.length} properties extracted`);
return results;
